head.script:
        	var bTabAdd = false;	// tabAdd() 한번만 호출

            /**************************************************************************
             * function    : init
             * Description : 폼 로딩 후 실행
             * Parameter   : null
             * Return      : null
             **************************************************************************/
            function init() {
            	tabAdd();
            }

            /**************************************************************************
             * function    : tabAdd
             * Description : 정의된 탭개수만큼 생성
             * Parameter   : null
             * Return      : null
             **************************************************************************/
            function tabAdd() {
            	var tabName = ["연도별", "기간별"];
				for (var i=0;i<2;i++) {
					var alwaysDraw = false;
					var idx = i+1;

					if(i==0) alwaysDraw = true; 
				   	var labelNm = tabName[i];
					if(i==0){
						var url = "/xml/cdttest/BISRnkYear.xml" + "?divisionId="+divisionId+"&divisionNm="+encodeURI(encodeURIComponent(labelNm))+"&tabIdx="+idx;
					} else if(i==1){
						var url = "/xml/cdttest/BISRnkTerm.xml" + "?divisionId="+divisionId+"&divisionNm="+encodeURI(encodeURIComponent(labelNm))+"&tabIdx="+idx;
					} 
				   	var tabOptions = { "label" : labelNm, "closable" : false, "class" : "sub_tab_btn"};
				   	var contentsOptions = {frameMode:"iframe", src: url, alwaysDraw:alwaysDraw};
				   	tabContents1.addTab('tabs' + idx, tabOptions, contentsOptions);

	            	if(alwaysDraw) {
	            		var objFrame = $("#tabContents1_contents_tabs"+idx+"_body");
						objFrame.removeClass("w2tabcontrol_contents_wrapper");
						objFrame.attr("title", labelNm+" content tab frame");
						objFrame.attr("scrolling", "no");
						objFrame.css("height", "");
						objFrame.attr("height", "0px");
				   	}
				   	tabContents1.setUserData( "tabContents1_tab_tabs"+idx , alwaysDraw );
				}
            }

            /**************************************************************************
             * function    : getGridPropertyNode
             * Description : 각 자식창 Tab에게 인스턴스를 전달하기 위한기능
             * Parameter   : tabID ( 보여질 Tab ID), idx(탭 인덱스 
             * Return      : null
             **************************************************************************/
            function getGridPropertyNode(idx, strNode) {
				var outputFormNo = getValue( "respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO[" + idx + "]/outputFormNo" );
				var arrXml = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/" + strNode + "[outputFormNo='" + outputFormNo + "']" );
				if (arrXml.length == 0) {
					var arr = strNode.split("/");
					var strXml = "<" + arr[1] + ">" + "</" + arr[1] + ">";
					arrXml = [WebSquare.xml.parse( strXml )]; 
				}
				return arrXml;
            }

            /**************************************************************************
             * function    : callBack
             * Description : submission 실행 후 Callback
             * Parameter   : retAction(submission 실행 Action), rowCount(조회 목록 총 건수)
             * Return      : null
             **************************************************************************/
            function callBack(svcId,fnId,strResp) {
            	var appNm = getValue("respWFrameHelp/root/message/proframeHeader/pfmAppName");
				var wfHelpSvcId = getValue("respWFrameHelp/root/message/BMNHelpDTO/serviceId");
				var divisionId = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO[1]/divisionId");
				var outFormSvcId = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO[1]/serviceId");

            	if (bTabAdd == true) return;

            	var arrObjNm = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/objNm").split("^");

               	if (svcId == "BISComStatisticsLinkSO") {
                	var arr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO" );
                  	if (arr.length > 0) {
                  		bTabAdd = true;
                    	tabAdd();
                  	} else {
                    	alert("그리드에 대한 정보가 존재하지 않습니다.");
                  	}
               	} else if (svcId == arrObjNm[1]) {
               		var gridXml = getInstanceNode("resp/root/message/BISComDspDatListDTO");
                  	if (getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/summaryRowCnt") > 0) {
                    	gridXml = setSubTotalData(grdMain);
                  	}

                  	grdMain.setXML( gridXml );

                  	if (getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/chartTyp") != "")
                    	chartShow();

                  	changeGridColumnPropery(grdMain);  // 셀 컬러 수정
               	}
            }

           	/**************************************************************************
             * function    : formChange
             * Description : Body 컬럼에 링크가 있을 경우 현 화면을 통해서 main의 iframe 소스를 변경
             * Parameter   : url ( 링크페이지 경로 )
             * Return      : null
             **************************************************************************/
            function formChange(url) {
            	parent.workFrame.setSrc(url);
            }

           	/**************************************************************************
             * function    : fnTreeview_ondblclick
             * Description : Body 컬럼에 링크가 있을 경우 현 화면을 통해서 main의 함수를 실행
             * Parameter   : label, value
             * Return      : null
             **************************************************************************/
            function fnTreeview_ondblclick( label, value ) {
               	parent.fnTreeview_ondblclick( label, value );    
            }


           /**************************************************************************
            * function    : resizeIframe
            * Description : iframe의 height를 재조정 한다.
            * Parameter   : 
            * Return      : 
            **************************************************************************/
	        function resizeIframe(height, tabIdx) {
				// 자식 iframe 크기 조절
				if(height != 0) {
					$("#tabContents1_contents_tabs"+tabIdx+"_body").attr("height", height+"px");
				}

				// 부모창 iframe 크기 조절
				var objParentIframe = parent.document.getElementById("maincontent");
				objParentIframe.height = (height+141)+"px";
			}

w2:tabControl.script:
var frameIdx = idx+1;
var isLoaded = tabContents1.getUserData( "tabContents1_tab_tabs"+frameIdx);
if(!isLoaded) {
	var objFrame = $("#tabContents1_contents_tabs"+frameIdx+"_body");
	var labelNm = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO["+frameIdx+"]/labelNm");
	objFrame.removeClass("w2tabcontrol_contents_wrapper");
	objFrame.attr("title", labelNm+" content tab frame");
	objFrame.attr("scrolling", "no");
	objFrame.css("height", "");
	objFrame.attr("height", "0px");
	tabContents1.setUserData( "tabContents1_tab_tabs"+frameIdx , true );
} else {
	$("#tabContents1_contents_tabs"+frameIdx+"_body")[0].contentWindow.resizeIframe();
}
tabContents1.setSelectedTabIndex( idx );
